```javascript
const card = document.querySelector('.card');
const button = card.querySelector('button');

card.addEventListener('click', () => console.log('card capture'), { capture: true });
button.addEventListener('click', () => console.log('button target'));
card.addEventListener('click', () => console.log('card bubble'));
```

```javascript
const form = document.querySelector('form');

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.reportValidity()) return;
  console.log('submit with fetch here');
});
```
The submit event can still bubble; only the default navigation is canceled.
